import argparse
import sys
from datetime import datetime

from .events import as_utc, count_events, events_since, read_events


def parse_since(text):
    """Parse a --since value. Dates are taken as midnight UTC, like naive timestamps."""
    try:
        value = datetime.fromisoformat(text)
        return as_utc(value)
    except (ValueError, OverflowError):
        raise argparse.ArgumentTypeError(
            f"invalid date/time {text!r}; expected e.g. 2024-03-10 or 2024-03-10T08:00:00+09:00"
        ) from None


def build_parser():
    parser = argparse.ArgumentParser(prog="evlog")
    commands = parser.add_subparsers(dest="command", required=True)
    report = commands.add_parser("report", help="count events per service and level")
    report.add_argument("path", help="events file (JSON lines)")
    report.add_argument(
        "--since",
        type=parse_since,
        metavar="DATE",
        help="only count events at or after this date/time (UTC unless an offset is given)",
    )
    return parser


def render(counts):
    lines = [f"{service} {level} {n}" for (service, level), n in sorted(counts.items())]
    lines.append(f"total {sum(counts.values())}")
    return "\n".join(lines)


def main(argv=None, out=None):
    out = out or sys.stdout
    args = build_parser().parse_args(argv)
    if args.command == "report":
        counts = count_events(read_events(args.path))
        print(render(counts), file=out)
    return 0
